[CmdletBinding()]param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop';$collector=Join-Path $RepositoryRoot 'Modules\ADHealth\Invoke-MSADPTADHealthCollection-v1.3.0.ps1';$temp=Join-Path ([IO.Path]::GetTempPath()) ('MSADPT-ADHealth-v130-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $temp|Out-Null;$csv=Join-Path $temp 'dcs.csv';@([pscustomobject]@{DomainController='DC01.example.test'},[pscustomobject]@{DomainController='DC02.example.test'})|Export-Csv $csv -NoTypeInformation
try{$r=& $collector -OutputRoot (Join-Path $temp 'out') -DomainControllerInventoryPath $csv -PlanOnly;if($r.Status-ne'Planned'){throw 'Plan-only status mismatch'};if($r.TargetCount-ne2){throw 'Target discovery mismatch'};if($r.CommandCount-ne15){throw "Expected 15 planned operations, got $($r.CommandCount)"};$p=Import-Csv $r.PlanPath;if(@($p|Where-Object{$_.Ports-match'135 TCP'}).Count-lt1){throw 'Port disclosure missing'};if(@($p|Where-Object{$_.OutputFile-eq'DCDiag-DC01.example.test.txt'}).Count-ne1){throw 'Deterministic output missing'};[pscustomobject]@{Status='Passed';TestVersion='1.3.0';TargetDiscoveryValidated=$true;PlanDisclosureValidated=$true;DeterministicFilenamesValidated=$true;NetworkActivity='None';ActiveDirectoryQueries='None';RemoteChanges='None'}}finally{Remove-Item $temp -Recurse -Force -ErrorAction SilentlyContinue}
